import {renderTeamBuilder} from './team-builder.js?v=team-2';
import {teamStorageKey} from './team-storage.js?v=team-2';
import {createBackup,parseBackup,planImport,applyImport} from './progress-backup.js?v=team-2';
import {readCompleted,readCaptures,toggleCompleted,cycleCapture,statusLabel,breedChildren,parentPairs,markerStorageKey,captureStorageKey} from './wiki-logic.js?v=tools-1';
import {loadLootTables,lootPoolsFor} from './chest-loot.js?v=loot-2';
const content=document.querySelector('#wiki-content'),feedback=document.querySelector('#wiki-feedback');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={Normal:'Neutral',Leaf:'Grass',Earth:'Ground',Electricity:'Electric',EmitFlame:'Kindling',Seeding:'Planting',Handcraft:'Handiwork',Collection:'Gathering',Deforest:'Lumbering',MonsterFarm:'Farming',ProductMedicine:'Medicine production',GenerateElectricity:'Generating electricity',Cool:'Cooling',Transport:'Transporting',hp:'HP',meleeAttack:'Melee attack',shotAttack:'Ranged attack',maleProbability:'Male probability (%)',foodAmount:'Food demand',attract:'Attraction multiplier',hitBar:'Hit bar multiplier',missFight:'Missed encounter multiplier',palDropBonus:'Pal drop bonus (source value)',itemDropBonus:'Item drop bonus (source value)'};
const pretty=v=>labels[v]||String(v??'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase());
const title=(name,intro)=>{document.title=`${name} · PalWaypoint`;document.querySelector('#wiki-title').textContent=name;document.querySelector('#wiki-intro').textContent=intro;};
const table=(heads,rows)=>`<div class="wiki-table-wrap"><table class="wiki-table"><thead><tr>${heads.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const summary=entries=>`<div class="wiki-summary">${entries.map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`;
const details=(name,body)=>`<details class="system-card"><summary>${esc(name)}</summary>${body}</details>`;
const options=values=>values.map(v=>`<option value="${esc(v)}">${esc(pretty(v))}</option>`).join('');
let data,palsById,itemMap,techMap,refresh=()=>{};
const itemName=id=>data.itemNames[id]||itemMap.get(id)?.name||id;
const palName=id=>palsById.get(id)?.name||id;
const itemArt=(id,style='item-icon')=>{const icon=itemMap.get(id)?.icon;return icon?`<img class="${style}" src="./${esc(icon)}" alt="" loading="lazy" decoding="async">`:'<span class="item-art-unavailable" aria-label="Artwork unavailable">?</span>';};
const itemLink=id=>itemMap.has(id)?`<a class="item-link" href="#item/${encodeURIComponent(id)}">${itemArt(id)}<span>${esc(itemName(id))}</span></a>`:esc(itemName(id));
const number=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:6}):'Not recorded';
const techLink=id=>techMap.has(id)?`<a href="#technology/${encodeURIComponent(id)}">${esc(techMap.get(id).name)}</a>`:esc(id);
const palLink=id=>palsById.has(id)?`<a href="#pal/${encodeURIComponent(id)}">${esc(palName(id))}</a>`:esc(palName(id));
const buildingName=id=>data.buildingNames[id]||id;
const badges=values=>values.map(v=>`<span class="wiki-badge">${esc(v)}</span>`).join('');
const unique=values=>[...new Set(values)].filter(Boolean).sort();
function captureButton(p){const state=readCaptures(localStorage)[p.id]||'uncaught';return `<button class="capture-sphere ${state}" data-capture="${esc(p.id)}" title="${esc(p.name)}: ${state==='complete'?'complete (5/5 captures)':state}. Click to cycle." aria-label="${esc(p.name)}: ${state==='complete'?'complete, 5 of 5 captures':state}; cycle capture status"><span class="sphere-art" aria-hidden="true"></span></button>`;}
function paginate(rows,draw,page,size=48){const total=Math.max(1,Math.ceil(rows.length/size));page.value=Math.min(page.value,total-1);draw(rows.slice(page.value*size,(page.value+1)*size));const target=document.querySelector('#wiki-results');target.insertAdjacentHTML('beforeend',`<div class="wiki-pages"><button id="page-prev" ${page.value===0?'disabled':''}>Previous</button><span class="wiki-count" aria-live="polite">${rows.length.toLocaleString()} results · Page ${page.value+1} of ${total}</span><button id="page-next" ${page.value===total-1?'disabled':''}>Next</button></div>`);document.querySelector('#page-prev').onclick=()=>{page.value--;refresh();};document.querySelector('#page-next').onclick=()=>{page.value++;refresh();};}
function filtered(fields,render){content.innerHTML=`<div class="wiki-toolbar">${fields.map(f=>`<label>${esc(f.label)}${f.values?`<select id="${f.id}"><option value="">${esc(f.all||'All')}</option>${options(f.values)}</select>`:`<input type="search" id="${f.id}" placeholder="${esc(f.placeholder||'Search')}" autocomplete="off">`}</label>`).join('')}</div><div id="wiki-results"></div>`;const page={value:0};refresh=()=>render(Object.fromEntries(fields.map(f=>[f.id,document.getElementById(f.id).value])),page);for(const f of fields)document.getElementById(f.id).addEventListener(f.values?'change':'input',()=>{page.value=0;refresh();});refresh();}
function pals(){title('Pals','Browse 288 numbered Pals and variants. Open a profile for stats, work suitability, learned skills and drops. Your capture sphere cycles through uncaught, caught and complete (5/5 captures).');filtered([{id:'search',label:'Find a Pal'},{id:'element',label:'Element',values:unique(data.pals.flatMap(p=>p.elements))},{id:'work',label:'Work',values:unique(data.pals.flatMap(p=>Object.keys(p.work)))},{id:'capture',label:'Capture status',values:['Uncaught','Caught','Complete']}],(f,page)=>{const captures=readCaptures(localStorage);const rows=data.pals.filter(p=>`${p.name} ${p.number}`.toLowerCase().includes(f.search.toLowerCase())&&(!f.element||p.elements.includes(f.element))&&(!f.work||p.work[f.work]>0)&&(!f.capture||(captures[p.id]||'uncaught')===f.capture.toLowerCase()));paginate(rows,shown=>{document.querySelector('#wiki-results').innerHTML=summary([['Caught',Object.keys(captures).filter(id=>palsById.has(id)).length+' / 288'],['Complete (5/5 captures)',Object.entries(captures).filter(([id,s])=>palsById.has(id)&&s==='complete').length]])+`<div class="wiki-grid">${shown.map(p=>`<article class="wiki-card"><div class="pal-card-heading"><img src="./icons/pals/${esc(p.id)}.webp" alt="" loading="lazy"><div><h3>${palLink(p.id)}</h3><div class="wiki-meta">#${esc(p.number)} · ${esc(p.elements.map(pretty).join(' / '))}</div></div>${captureButton(p)}</div>${badges(Object.entries(p.work).filter(([,v])=>v>0).map(([k,v])=>`${pretty(k)} ${v}`))}</article>`).join('')}</div>`;},page);});}
function palHabitats(p){const entries=Object.entries(p.spawnMaps||{});return `<h2>Habitats &amp; wild spawns</h2>${entries.length?table(["Map","Field spawn locations","Day habitat points","Night habitat points","Explore"],entries.map(([map,h])=>[map==="tree"?"World Tree":"Palpagos Islands",number(h.placements),number(h.dayHabitatPoints),number(h.nightHabitatPoints),`<a href="./index.html?map=${map==="tree"?"tree":"islands"}&amp;pal=${encodeURIComponent(p.id)}&amp;palName=${encodeURIComponent(p.name)}">View day/night habitat</a>`])):`<p class="wiki-count">No wild habitat or common field spawn is recorded for this Pal in the installed-build tables. It may be obtained through other encounters or breeding.</p>`}<p class="wiki-count">Paldeck habitat points describe the game’s habitat display. Field locations show possible spawns, which can depend on time, weather and other conditions.</p>`;}
function profile(id){const p=palsById.get(id);if(!p)return missing();title(p.name,`#${p.number} · ${p.elements.map(pretty).join(' / ')}${p.nocturnal?' · Nocturnal':''}`);content.innerHTML=`<a class="wiki-back" href="#pals">← Every Pal</a><div class="wiki-profile-heading"><img class="profile-portrait" src="./icons/pals/${esc(id)}.webp" alt=""><div class="wiki-prose wiki-description">${esc(p.description)}</div>${captureButton(p)}</div>${palHabitats(p)}<h2>Base stats</h2>${table(['Stat','Value'],Object.entries(p.stats).map(([k,v])=>[esc(pretty(k)),esc(v)]))}<h2>Work suitability</h2>${badges(Object.entries(p.work).filter(([,v])=>v>0).map(([k,v])=>`${pretty(k)} · Level ${v}`))}<h2>Possible drops</h2>${table(['Item','Quantity','Drop chance'],p.drops.map(d=>[itemLink(d.item),`${d.min}–${d.max}`,`${esc(d.rate)}%`]))}<h2>Learned skills</h2>${table(['Level','Skill','Element','Power','Cooldown'],p.skills.map(s=>[esc(s.level),esc(s.name),esc(s.element),esc(s.power),`${esc(s.coolTime)} s`]))}<p class="wiki-count">Breeding rank: ${esc(p.rank)} · <a href="#breeding">Plan a pairing</a></p>`;refresh=()=>profile(id);}
function items(){title('Items','Search 1,892 records from the server-derived Atlas item catalog. Records may include unused or unavailable items; a record alone does not establish that it can be obtained.');filtered([{id:'search',label:'Find an item'},{id:'category',label:'Category',values:unique(data.items.map(i=>i.category))},{id:'rarity',label:'Rarity',values:unique(data.items.map(i=>String(i.rarity)))}],(f,page)=>{const rows=data.items.filter(i=>`${i.name} ${i.id}`.toLowerCase().includes(f.search.toLowerCase())&&(!f.category||i.category===f.category)&&(!f.rarity||String(i.rarity)===f.rarity));paginate(rows,shown=>{document.querySelector('#wiki-results').innerHTML=`<div class="wiki-grid">${shown.map(i=>`<article class="wiki-card"><div class="item-card-heading"><h3>${itemLink(i.id)}</h3></div><div class="wiki-meta">${esc(i.category)} · Rarity ${esc(i.rarity)}</div><p>${esc(i.description.slice(0,180))}</p></article>`).join('')}</div>`;},page);});}
function itemProfile(id){const i=itemMap.get(id);if(!i)return missing();title(i.name,`${unique([i.category,i.subcategory]).join(' · ')} · Rarity ${i.rarity}`);content.innerHTML=`<a class="wiki-back" href="#items">← Item catalog</a><div class="wiki-profile-heading item-profile-heading">${itemArt(id,'item-portrait')}<div class="wiki-prose wiki-description">${esc(i.description)}</div></div>${summary([['Weight',i.weight],['Base price',typeof i.price==='number'?number(i.price)+' gold':'Not recorded'],['Max stack',number(i.maxStack)]])}${itemUnlocks(i)}${i.recipe?`<h2>Recipe</h2>${table(['Material','Quantity'],(i.recipe.materials||[]).map(m=>[itemLink(m.item),esc(number(m.count))]))}<p class="wiki-count">Crafted at: ${(i.recipe.craftedAt||[]).map(x=>esc(buildingName(x))).join(', ')||'Not specified'} · Output: ${esc(number(i.recipe.productCount??1))}${i.recipe.work!=null?' · '+esc(number(i.recipe.work))+' work':''}</p>`:''}${i.unlocksCraft?.length?`<h2>Recipes this schematic unlocks</h2><p>${i.unlocksCraft.map(itemLink).join(' · ')}</p>`:''}<h2>Recorded sources</h2>${i.sources?.length?table(['Source','Details','Table chance'],i.sources.map(s=>[esc(pretty(s.kind)),esc([s.area,s.grade!=null?`Grade ${s.grade}`:'',s.merchant?`Shop ${s.merchant}`:''].filter(Boolean).join(' · ')),s.chance!=null?`${esc(s.chance)}%`:'—'])):'<p class="wiki-count">No acquisition source is recorded in these tables.</p>'}${i.droppedBy?.length?`<h2>Dropped by</h2><p>${i.droppedBy.map(p=>palLink(p.id)).join(' · ')}</p>`:''}<p class="wiki-count">Source odds describe table rolls, not the probability a chest or item spawns at a location.</p>`;}

function itemUnlocks(i){
  const technologies=(i.unlockTech||[]).map(id=>techMap.get(id)).filter(Boolean),schematics=i.unlockSchematics||[],cards=[];
  if(technologies.length)cards.push(`<section class="unlock-card"><h3>Unlocked by technology</h3>${technologies.map(t=>`<p>${techLink(t.id)}</p><p class="wiki-count">Technology level ${esc(t.level)} · ${esc(t.cost)} ${t.isBoss?'Ancient Technology':'Technology'} points</p>`).join('')}<a href="#technology">View the whole technology tree →</a></section>`);
  if(schematics.length)cards.push(`<section class="unlock-card"><h3>Unlocked by schematic</h3>${schematics.map(id=>`<p>${itemLink(id)}</p>`).join('')}<p class="wiki-count">This recipe requires the matching schematic.</p></section>`);
  if(!cards.length){const methods=unique((i.sources||[]).map(s=>s.kind)),ranch=data.pals.filter(p=>(p.farm||[]).some(level=>level.some(r=>r.item===i.id)));let text=i.recipe?'No technology or schematic requirement is recorded for this recipe.':methods.length||i.droppedBy?.length||ranch.length?'No crafting unlock is recorded. See the acquisition methods below.':'An unlock or acquisition method is not recorded for this item. It may be unused or unavailable.';cards.push(`<section class="unlock-card"><h3>Unlock & acquisition</h3><p>${text}</p>${methods.length?`<p class="wiki-count">Recorded methods: ${methods.map(pretty).map(esc).join(', ')}.</p>`:''}${methods.some(k=>['chest','oilrig','treasureMap'].includes(k))?'<a href="#chest-loot">Browse chest loot tables →</a>':''}${methods.includes('merchant')?'<p><a href="#merchants">Browse merchant inventories →</a></p>':''}${methods.includes('fishing')?'<p><a href="#fishing">Browse fishing tables →</a></p>':''}${ranch.length?`<p>Ranch production: ${ranch.map(p=>palLink(p.id)).join(', ')}. <a href="#ranch">View production quantities →</a></p>`:''}</section>`);}
  return '<h2>How to unlock</h2><div class="unlock-grid">'+cards.join('')+'</div>';
}
function technologyProfile(id){const t=techMap.get(id);if(!t)return missing();title(t.name,`${t.isBoss?'Ancient Technology':'Technology'} · Level ${t.level}`);content.innerHTML=`<a class="wiki-back" href="#technology">← Whole technology tree</a>${summary([['Required level',t.level],[t.isBoss?'Ancient Technology points':'Technology points',t.cost]])}${t.description?`<p class="wiki-prose">${esc(t.description)}</p>`:''}<h2>Unlocks</h2><div class="wiki-prose">${(t.unlockItems||[]).map(id=>`<p>${itemLink(id)}</p>`).join('')}${(t.unlockBuildings||[]).map(id=>`<p>${esc(buildingName(id))}</p>`).join('')}</div>`;}

function ranch(){
  title('Ranch','Compare every ranch Pal and its possible products at a glance. Quantities are shown at partner-skill levels 1, 5 and 10, using the independently extracted production tables. These are possible outcomes, not guaranteed production per interval.');
  const levels=[0,4,9],pals=data.pals.filter(p=>p.work.MonsterFarm>0&&p.farm?.length).sort((a,b)=>a.name.localeCompare(b.name));
  const productsFor=p=>unique(levels.flatMap(level=>(p.farm[level]||[]).map(r=>r.item))).sort((a,b)=>itemName(a).localeCompare(itemName(b)));
  const quantity=(p,item,level)=>{const rolls=(p.farm[level]||[]).filter(r=>r.item===item);return rolls.length?rolls.map(r=>r.min===r.max?esc(r.min):`${esc(r.min)}–${esc(r.max)}`).join(' / '):'<span aria-label="Not in this level’s production table">—</span>';};
  content.innerHTML=summary([['Ranch Pals',pals.length],['Distinct products',new Set(pals.flatMap(productsFor)).size]])+
    `<div class="wiki-table-wrap ranch-table-wrap" role="region" aria-label="Ranch Pal production comparison" tabindex="0"><table class="wiki-table ranch-table"><caption>Possible production quantities · A dash means the product is absent from that level’s table.</caption><thead><tr>${['Pal','Farming level','Product','Lv 1','Lv 5','Lv 10'].map(name=>`<th scope="col">${esc(name)}</th>`).join('')}</tr></thead>${pals.map(p=>{const products=productsFor(p);return `<tbody>${products.map((item,index)=>`<tr>${index===0?`<th scope="rowgroup" rowspan="${products.length}"><span class="ranch-pal"><img src="./icons/pals/${esc(p.id)}.webp" alt="" loading="lazy">${palLink(p.id)}</span></th><td rowspan="${products.length}" class="ranch-work">${esc(p.work.MonsterFarm)}</td>`:''}<td>${itemLink(item)}</td>${levels.map(level=>`<td class="ranch-quantity">${quantity(p,item,level)}</td>`).join('')}</tr>`).join('')}</tbody>`;}).join('')}</table></div>`;
}
function breeding(){
  title('Breeding','Calculate an offspring or choose a target Pal to find its parent pairs. Results use the independently extracted breeding ranks and special recipes.');
  const choices=data.pals.filter(p=>data.breeding.pals.some(b=>b.id===p.id)).sort((a,b)=>a.name.localeCompare(b.name));
  const select=choices.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');
  content.innerHTML=`<nav class="tool-tabs" aria-label="Breeding mode"><button id="breed-forward" type="button" aria-pressed="true">Parents → offspring</button><button id="breed-reverse" type="button" aria-pressed="false">Offspring → parents</button></nav><section id="breed-forward-panel"><div class="wiki-toolbar"><label>Parent A<select id="parent-a"><option value="">Choose a Pal</option>${select}</select></label><label>Parent B<select id="parent-b"><option value="">Choose a Pal</option>${select}</select></label><button id="breed-swap" type="button">Swap parents</button></div><div id="breed-result" aria-live="polite">Choose both parents.</div></section><section id="breed-reverse-panel" hidden><div class="wiki-toolbar"><label>Target offspring<select id="breed-target"><option value="">Choose a Pal</option>${select}</select></label><label>Find a parent<input id="breed-parent-search" type="search" placeholder="Parent name"></label></div><label class="tool-check"><input id="breed-owned" type="checkbox">Only pairs where I’ve caught both parents</label><div id="wiki-results" aria-live="polite"></div></section><h2>How the result is chosen</h2><div class="wiki-prose"><p>The same species produces that species. Special recipes override the general rule. Otherwise, the child is the eligible Pal closest to the rounded mean of the parents’ breeding ranks, using the source table’s tie-breaking priority.</p><p>Reverse search covers every unordered pairing of the ${choices.length} Pals in this catalog, including same-species and special pairings. Gender-specific recipes show the required male and female. A pair needs opposite-sex parents. <a href="#teams">Estimate passive inheritance in the team planner</a>. The estimator states its parents-only assumptions; IV inheritance is not yet calculated.</p></div>`;
  const updateForward=()=>{const a=document.querySelector('#parent-a').value,b=document.querySelector('#parent-b').value;const results=breedChildren(data.breeding,a,b);document.querySelector('#breed-result').innerHTML=results.length?results.map(r=>`<article class="wiki-card"><h2>${palLink(r.id)}</h2><p>${esc(r.rule)}${r.target!=null?` · Rank ${r.left} + ${r.right} → target ${r.target}`:''}</p>${r.gender?`<p>${esc(r.gender.replace(/([\w]+):/g,(_,id)=>palName(id)+':'))}</p>`:''}</article>`).join(''):'Choose both parents.';};
  const page={value:0};
  const updateReverse=()=>{
    const target=document.querySelector('#breed-target').value,q=document.querySelector('#breed-parent-search').value.trim().toLowerCase(),owned=document.querySelector('#breed-owned').checked,captures=readCaptures(localStorage);
    if(!target){document.querySelector('#wiki-results').innerHTML='<p>Choose the Pal you want to hatch.</p>';return;}
    const pairs=parentPairs(data.breeding,target).filter(r=>palsById.has(r.a)&&palsById.has(r.b)&&(!q||`${palName(r.a)} ${palName(r.b)}`.toLowerCase().includes(q))&&(!owned||(captures[r.a]&&captures[r.b]))).sort((a,b)=>(a.rule==='Same species')-(b.rule==='Same species')||palName(a.a).localeCompare(palName(b.a))||palName(a.b).localeCompare(palName(b.b)));
    paginate(pairs,shown=>{document.querySelector('#wiki-results').innerHTML=`<h2>Parents for ${esc(palName(target))}</h2>`+(shown.length?table(['Parent A','Parent B','Pairing rule','Required genders'],shown.map(r=>[palLink(r.a),palLink(r.b),esc(r.rule),r.gender?esc(r.gender.replace(/([\w]+):/g,(_,id)=>palName(id)+':')):'One male and one female'])):'<p>No pairs match these filters. Try clearing the parent search or caught-only filter.</p>');},page);
  };
  let reverse=false;refresh=()=>reverse?updateReverse():updateForward();
  for(const [id,value] of [['breed-forward',false],['breed-reverse',true]])document.getElementById(id).onclick=()=>{reverse=value;document.querySelector('#breed-forward-panel').hidden=value;document.querySelector('#breed-reverse-panel').hidden=!value;document.querySelector('#breed-forward').setAttribute('aria-pressed',String(!value));document.querySelector('#breed-reverse').setAttribute('aria-pressed',String(value));refresh();};
  for(const id of ['parent-a','parent-b'])document.getElementById(id).onchange=updateForward;
  document.querySelector('#breed-swap').onclick=()=>{const a=document.querySelector('#parent-a'),b=document.querySelector('#parent-b');[a.value,b.value]=[b.value,a.value];updateForward();};
  for(const id of ['breed-target','breed-parent-search','breed-owned'])document.getElementById(id).addEventListener(id==='breed-parent-search'?'input':'change',()=>{page.value=0;updateReverse();});
  updateReverse();
}

function technology(){title('Technology','588 technology records, including Ancient Technology. Search unlock names or filter by level; costs and unlocks come from the extracted tables.');filtered([{id:'search',label:'Find technology'},{id:'level',label:'Level',values:unique(data.techs.map(t=>String(t.level))).sort((a,b)=>a-b)},{id:'kind',label:'Tree',values:['Standard','Ancient']}],(f,page)=>{const rows=data.techs.filter(t=>`${t.name} ${t.description}`.toLowerCase().includes(f.search.toLowerCase())&&(!f.level||String(t.level)===f.level)&&(!f.kind||Boolean(t.isBoss)===(f.kind==='Ancient')));paginate(rows,shown=>{document.querySelector('#wiki-results').innerHTML=table(['Level','Technology','Point cost','Unlocks'],shown.map(t=>[esc(t.level),`${techLink(t.id)}<small>${t.isBoss?'Ancient':'Standard'}</small>`,esc(t.cost),[...(t.unlockItems||[]).map(itemLink),...(t.unlockBuildings||[]).map(b=>esc(buildingName(b)))].join(', ')]));},page);});}
function fishing(){title('Fishing','115 fishing tables and nine bait records. Table share is the source’s normalized pool share; time, difficulty and other conditions can affect the actual encounter.');content.innerHTML=`<h2>Baits</h2>${table(['Bait','Recorded modifiers'],data.fishing.baits.map(b=>[itemLink(b.item),Object.entries(b).filter(([k])=>k!=='item').map(([k,v])=>`${esc(pretty(k))}: ${esc(v)}`).join(' · ')||'None specified']))}<h2>Fishing pools</h2><div class="wiki-toolbar"><label>Find a region or Pal<input id="fish-search" type="search"></label></div><div id="fish-results"></div>`;const render=()=>{const query=document.querySelector('#fish-search').value.toLowerCase();document.querySelector('#fish-results').innerHTML=data.fishing.spots.filter(s=>`${s.area} ${s.id} ${s.fish.map(f=>palName(f.pal)).join(' ')}`.toLowerCase().includes(query)).map(s=>details(`${s.area} · ${s.id} · Difficulty ${s.spotDifficulty}`,table(['Pal','Level','Table share','Conditions'],s.fish.map(f=>[palLink(f.pal),`${f.lvMin}–${f.lvMax}`,`${f.sharePct}%`,esc([f.night?'Night':'',f.alpha?'Alpha':'',f.boss?'Boss':'',f.rare?'Rare':''].filter(Boolean).join(' · ')||'None specified')])))).join('');};document.querySelector('#fish-search').oninput=render;render();}
async function chests(key=''){
  title('Chest loot','Browse game loot pools by region, container and grade. Item chances are weight shares within one grade and slot; each slot has its own chance to roll.');
  content.innerHTML='<p>Loading chest grades…</p>';const routeHash=location.hash;
  try{
    const [catalog,tips]=await Promise.all([loadLootTables(),fetch('./chest-tips.json?v=loot-1').then(r=>r.json())]);if(location.hash!==routeHash)return;
    const scoped=lootPoolsFor(catalog,key,tips),regions=unique(scoped.map(p=>p.region));
    const overview=summary([['Loot pools',scoped.length],['Grade tables',scoped.reduce((n,p)=>n+Object.keys(p.grades).length,0)],['Game build',catalog.build]]);
    const note='<p class="wiki-count">Grades stay separate. Percentages in each slot total 100%; the slot activation chance is shown above it. These are table shares, not chest appearance or grade-selection probabilities. Availability links use the chest spawners recovered from the game. Pools without a linked placement remain listed as game tables.</p>';
    filtered([{id:'loot-search',label:'Find an item or pool'},{id:'loot-region',label:'Region',values:regions},{id:'loot-kind',label:'Container',values:unique(scoped.map(p=>p.kind))},{id:'loot-grade',label:'Grade',values:unique(scoped.flatMap(p=>Object.keys(p.grades)))}],(f,page)=>{
      const q=f['loot-search'].toLowerCase();const pools=scoped.filter(p=>(!f['loot-region']||p.region===f['loot-region'])&&(!f['loot-kind']||p.kind===f['loot-kind']));
      const cards=pools.flatMap(p=>Object.entries(p.grades).filter(([g,slots])=>(!f['loot-grade']||g===f['loot-grade'])&&(!q||[p.label,p.region,...slots.flatMap(s=>s.entries.map(e=>e.name))].join(' ').toLowerCase().includes(q))).map(([grade,slots])=>({pool:p,grade,slots})));
      paginate(cards,shown=>{document.querySelector('#wiki-results').innerHTML='<div class="loot-grid">'+shown.map(({pool:p,grade,slots})=>'<article class="loot-card"><p class="loot-region">'+esc(p.region)+'</p><h2>'+esc(p.label)+'</h2><p class="wiki-meta">'+esc(p.kind)+' · Grade '+esc(grade)+'</p><p class="wiki-count">'+(p.locationCount?p.locationCount+' linked locations · '+p.maps.map(map=>'<a href="./index.html?map='+(map==='World Tree'?'tree':'islands')+'&category='+encodeURIComponent(p.kind.split(' / ')[0])+'&loot='+encodeURIComponent(p.id)+'">View '+esc(map)+'</a>').join(' · '):'No overworld placement linked to this pool.')+'</p>'+slots.map(slot=>'<section class="loot-slot"><h3>Slot '+slot.slot+' · '+(slot.activation===100?'Always rolls':number(slot.activation)+'% chance to roll')+'</h3>'+table(['Item','Chance in slot','Quantity'],slot.entries.filter(e=>!q||[p.label,p.region].join(' ').toLowerCase().includes(q)||e.name.toLowerCase().includes(q)).map(e=>[itemLink(e.wikiId||e.id),'<span class="loot-chance">'+number(Number(e.share.toFixed(2)))+'%</span><span class="loot-bar" aria-hidden="true"><span style="width:'+e.share+'%"></span></span>','×'+number(e.min)+(e.min===e.max?'':'–'+number(e.max))]))+'</section>').join('')+'</article>').join('')+'</div>'+(shown.length?'':'<p>No matching loot tables.</p>');},page,12);
    });
    content.insertAdjacentHTML('afterbegin',overview+note+(key?'<p><a href="#chest-loot">Browse all regions and pools →</a></p>':'')+'<nav class="loot-regions" aria-label="Jump to region">'+regions.map(r=>'<button type="button" data-loot-region="'+esc(r)+'">'+esc(r)+'</button>').join('')+'</nav>');
    for(const b of content.querySelectorAll('[data-loot-region]'))b.onclick=()=>{const select=document.querySelector('#loot-region');select.value=b.dataset.lootRegion;select.dispatchEvent(new Event('change'));document.querySelector('#wiki-results').scrollIntoView({block:'start'});};
  }catch{if(location.hash===routeHash)content.innerHTML='<p>Chest loot could not load. <a href="#chest-loot">Retry</a></p>';}
}

function base(){title('Base camp','Base progression across 35 recorded levels, including worker limits, base limits and upgrade tasks. This first release covers progression and construction requirements; raids, research and production planning remain to be added.');content.innerHTML=data.baseLevels.map(l=>details(`Level ${l.level} · ${l.workers} workers · ${l.bases} bases`,table(['Task','Requirement','Construction materials'],(l.tasks||[]).map(t=>{const b=data.buildings.find(b=>b.id===t.object);return [esc(t.object?buildingName(t.object):'Workers'),esc(t.count??t.workers??'—'),b?.materials?.map(m=>`${itemLink(m.item)} ×${m.count}`).join(', ')||'—'];})))).join('');}
function merchants(){title('Merchants','39 recorded shop inventories. Prices are tied to each shop and its currency. A table does not establish that a merchant is always present or that every item is available on every visit.');content.innerHTML=data.merchants.map(m=>details(`${pretty(m.nameKey)} shop · ${m.id}`,`<p class="wiki-count">Currency: ${itemLink(m.currency)}</p>${table(['Product','Price','Quantity','Limit'],m.products.map(p=>[itemLink(p.item),esc(p.price),esc(p.num??1),p.onceOnly?'Once only':'Not specified']))}`)).join('');}
function mapLink(l){return `./index.html?map=${encodeURIComponent(l.map)}&category=${encodeURIComponent(l.category)}&marker=${encodeURIComponent(l.id)}`;}
function checklist(){title('Your checklist','The same saved progress used by the interactive map: collectibles, fast travel, encounters, ruins, caves and dungeons across both maps. Changes here update the map, including another open tab.');filtered([{id:'search',label:'Find a location'},{id:'map-filter',label:'Map',values:['Palpagos Islands','World Tree']},{id:'category',label:'Category',values:unique(data.locations.map(l=>l.category))},{id:'status',label:'Show',values:['Remaining','Completed']}],(f,page)=>{const completed=readCompleted(localStorage);const rows=data.locations.filter(l=>`${l.name} ${l.category}`.toLowerCase().includes(f.search.toLowerCase())&&(!f['map-filter']||(l.map==='tree'?'World Tree':'Palpagos Islands')===f['map-filter'])&&(!f.category||l.category===f.category)&&(!f.status||completed.has(l.id)===(f.status==='Completed')));const count=data.locations.filter(l=>completed.has(l.id)).length;paginate(rows,shown=>{document.querySelector('#wiki-results').innerHTML=summary([['Completed',count],['Remaining',data.locations.length-count],['Tracked locations',data.locations.length]])+`<progress value="${count}" max="${data.locations.length}" aria-label="Location completion"></progress>`+table(['Status','Location','Category','Map','Coordinates'],shown.map(l=>[`<label><input type="checkbox" data-location="${esc(l.id)}" ${completed.has(l.id)?'checked':''} aria-label="${esc(statusLabel(l.category)+' '+l.name)}"> ${esc(statusLabel(l.category))}</label>`,`<a href="${mapLink(l)}">${esc(l.name)}</a>`,esc(l.category),l.map==='tree'?'World Tree':'Islands',`${Math.round(l.x)}, ${Math.round(l.y)}`]));},page);});}
function backup(){
  title('Back up & restore progress','Download your saved teams, completed map locations and Pal capture statuses, then import them on another browser or device. Files stay on your device.');
  content.innerHTML=`<div class="wiki-grid backup-grid"><article class="wiki-card"><h2>Download a backup</h2><p>Includes saved teams, progress from both maps, caught and complete Pals, and your hide-completed setting. This is a PalWaypoint backup, not a Palworld game save.</p><div id="backup-current"></div><button id="backup-export" type="button">Download progress backup</button></article><article class="wiki-card"><h2>Import a backup</h2><label class="tool-file">Choose a PalWaypoint JSON backup<input id="backup-file" type="file" accept=".json,application/json"></label><fieldset class="import-modes"><legend>How to restore</legend><label><input type="radio" name="import-mode" value="merge" checked>Merge with saved progress</label><p>Keeps completed locations from both copies and the higher capture status. Conflicting versions of a team are kept as separate copies. Your current settings stay as they are.</p><label><input type="radio" name="import-mode" value="replace">Replace saved progress</label><p>Uses only the backup’s locations and capture statuses, including its saved setting. Saved teams are replaced when the file includes teams; older backups without teams leave your teams untouched. Download your current progress first if you want to keep it.</p></fieldset><div id="backup-preview" aria-live="polite">Choose a file to preview it before importing.</div><button id="backup-import" type="button" disabled>Import and merge progress</button><p id="backup-status" role="status"></p></article></div><p class="wiki-count">Imports retain saved IDs even if they are absent from the current catalog, so older or newer backups do not silently lose records. Map and checklist tabs update automatically. Account synchronization is not required.</p>`;
  let selected=null,sequence=0;
  const counts=v=>`${number(v.completed.length)} completed locations · ${number(Object.keys(v.captures).length)} caught Pals · ${number(Object.values(v.captures).filter(s=>s==='complete').length)} complete · ${v.teams===undefined?'teams not included':number(v.teams.length)+' saved teams'}`;
  const status=document.querySelector('#backup-status'),button=document.querySelector('#backup-import');
  const mode=()=>document.querySelector('input[name="import-mode"]:checked').value;
  const render=()=>{
    try{document.querySelector('#backup-current').innerHTML=`<p class="wiki-count">${esc(counts(createBackup(localStorage)))}</p>`;
      button.textContent=mode()==='merge'?'Import and merge progress':'Replace progress with this backup';button.disabled=!selected;
      if(selected){const next=planImport(localStorage,selected,mode());const known=new Set(data.locations.map(l=>l.id)),unknown=selected.completed.filter(id=>!known.has(id)).length;document.querySelector('#backup-preview').innerHTML=`<p><strong>Backup:</strong> ${esc(counts(selected))}</p><p><strong>After ${mode()==='merge'?'merging':'replacement'}:</strong> ${esc(counts(next))}</p>${unknown?`<p>${number(unknown)} location IDs are outside this catalog and will be retained.</p>`:''}`;}
    }catch(error){status.textContent=error.message;button.disabled=true;}
  };refresh=render;
  document.querySelector('#backup-export').onclick=()=>{try{const snapshot=createBackup(localStorage),blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`palwaypoint-progress-${new Date().toISOString().replace(/[:.]/g,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Backup downloaded. Keep the file somewhere you can find it.';}catch{status.textContent='Could not read progress from this browser.';}};
  document.querySelector('#backup-file').onchange=async event=>{const request=++sequence;selected=null;status.textContent='';button.disabled=true;document.querySelector('#backup-preview').textContent='Checking the backup…';const file=event.target.files[0];if(!file){document.querySelector('#backup-preview').textContent='Choose a file to preview it before importing.';return;}try{if(file.size>2_000_000)throw Error('Choose a backup smaller than 2 MB.');const parsed=parseBackup(await file.text());if(request!==sequence||!button.isConnected)return;selected=parsed;render();}catch(error){if(request!==sequence||!button.isConnected)return;status.textContent=error.message;document.querySelector('#backup-preview').textContent='Nothing was imported. Your saved progress is unchanged.';}};
  for(const input of document.querySelectorAll('input[name="import-mode"]'))input.onchange=render;
  button.onclick=()=>{if(!selected)return;try{const result=applyImport(localStorage,selected,mode());render();status.textContent=`Progress ${mode()==='merge'?'merged':'replaced'}: ${counts(result)}. Your map and checklist use the restored progress.`;}catch(error){status.textContent=error.message;}};
  render();
}

let effigyCatalog;
async function effigies(){
  title('Effigies','Compare the abilities unlocked by each Pal Effigy and plan your upgrades at a Statue of Power. Upgrade costs and effect descriptions come directly from the installed game files.');
  content.innerHTML='<p>Loading effigy upgrades…</p>';const hash=location.hash;
  try{
    if(!effigyCatalog){const response=await fetch('./effigies.json?v=tools-1');if(!response.ok)throw Error('Unavailable');effigyCatalog=await response.json();}
    if(hash!==location.hash)return;
    const catalog=effigyCatalog,completed=readCompleted(localStorage),locations=data.locations.filter(l=>l.category.endsWith('Effigy'));
    content.innerHTML=summary([['Upgrade types',catalog.groups.length],['Mapped effigies',locations.length],['Collected on map',locations.filter(l=>completed.has(l.id)).length]])+`<p class="wiki-count">Game build ${number(catalog.build)}. Map checkboxes record locations you collected; they do not track spent effigies or your current in-game upgrade level.</p><h2>Every effigy &amp; ability</h2>`+table(['Effigy','Ability','Effect','Max level','Total upgrade cost','Locations'],catalog.groups.map(g=>{const group=locations.filter(l=>l.category===g.name);return [`${g.icon?`<img class="item-icon" src="${esc(g.icon)}" alt=""> `:''}<button class="effigy-pick" type="button" data-effigy="${esc(g.id)}">${esc(g.name)}</button>`,esc(g.effect),esc(g.description),number(g.maxLevel),number(g.totalCost)+' effigies',group.length?`${number(group.filter(l=>completed.has(l.id)).length)} / ${number(group.length)} collected · ${unique(group.map(l=>l.map)).map(map=>`<a href="./index.html?map=${map}&category=${encodeURIComponent(g.name)}">${map==='tree'?'World Tree':'Islands'} map</a>`).join(' · ')}`:esc(g.acquisition==='Capture bonus completion'?'Reward for completing a Pal’s capture bonus':'No mapped locations')];}))+
      `<h2 id="effigy-planner">Upgrade planner</h2><div class="wiki-toolbar"><label>Effigy<select id="effigy-type">${catalog.groups.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></label><label>Current upgrade level<select id="effigy-current"></select></label><label>Target level<select id="effigy-target"></select></label></div><div id="effigy-estimate" aria-live="polite"></div><div id="effigy-levels"></div><p class="wiki-count">Effect values below are shown as recorded in the game table; a value is not an unconditional catch chance. Capture Power uses its upgrade rank and has no percentage effect in this table. This installed build may differ from other versions or community tables.</p>`;
    const type=document.querySelector('#effigy-type'),current=document.querySelector('#effigy-current'),target=document.querySelector('#effigy-target');
    const render=()=>{
      const g=catalog.groups.find(g=>g.id===type.value),from=Number(current.value),to=Number(target.value),steps=g.levels.filter(r=>r.level>from&&r.level<=to),needed=steps.reduce((n,r)=>n+r.cost,0);
      document.querySelector('#effigy-estimate').innerHTML=to<from?'<p>Choose a target level equal to or above your current level.</p>':summary([['Effigies needed',number(needed)],['Upgrade steps',number(steps.length)],['Target ability',g.effect+' · Level '+to]]);
      document.querySelector('#effigy-levels').innerHTML=`<h2>${esc(g.name)} upgrade costs</h2><p>${esc(g.description)}</p>`+table(['Level','Cost for this level','Total from level 0',g.id==='CapturePower'?'Capture Power rank':'Recorded effect value'],g.levels.map(r=>[number(r.level),number(r.cost),number(r.total),g.id==='CapturePower'?'Rank '+number(r.level):number(r.effectValue)]));
    };
    const choose=()=>{const g=catalog.groups.find(g=>g.id===type.value),values=Array.from({length:g.maxLevel+1},(_,i)=>`<option value="${i}">${i}</option>`).join('');current.innerHTML=values;target.innerHTML=values;target.value=String(g.maxLevel);render();};
    type.onchange=choose;current.onchange=render;target.onchange=render;
    for(const b of content.querySelectorAll('[data-effigy]'))b.onclick=()=>{type.value=b.dataset.effigy;choose();document.querySelector('#effigy-planner').scrollIntoView({block:'start'});};
    refresh=()=>{const selected=type.value,from=current.value,to=target.value;effigies().then(()=>{if(location.hash!==hash)return;document.querySelector('#effigy-type').value=selected;document.querySelector('#effigy-type').dispatchEvent(new Event('change'));document.querySelector('#effigy-current').value=from;document.querySelector('#effigy-target').value=to;document.querySelector('#effigy-current').dispatchEvent(new Event('change'));});};
    choose();
  }catch{if(location.hash===hash)content.innerHTML='<p>Effigy upgrade data could not load. <button id="effigy-retry" type="button">Retry</button></p>';document.querySelector('#effigy-retry')?.addEventListener('click',effigies);}
}

function prose(kind){const pages={guide:['Using PalWaypoint','Map and field guide work together.',`<h2>Explore</h2><p>Choose Islands or World Tree, select marker categories, and click a pin for its coordinates and details. Zoom out to see grouped markers; zoom in to choose a location. In the Pals tab, choose Map beside a Pal to display its habitat heatmap and spawn pins. Switch All, Day or Night to compare availability. Hover or tap near a shaded spawn area for encounter groups, pack sizes, levels and weighted chances. The heat is approximate habitat concentration; each percentage belongs to one encounter group in one field spawn pool.</p><h2>Track</h2><p>Use the relevant Unlocked, Activated, Cleared, Defeated or Collected checkbox in a map popup. The checklist reads those same records and links back to individual pins.</p><p>The capture sphere cycles uncaught → caught → complete (5/5 captures) → uncaught. This is a manual species tracker, not a live count from your save file.</p><h2>Keep your progress</h2><p>Progress is saved in this browser on this device. Private browsing, clearing site data, or changing browsers can remove or separate it. Use <a href="#backup">Back up &amp; restore</a> to download progress or import it on another browser. Account sync is not available.</p>`],about:['About & sources','An independent Palworld field guide, with clear data provenance.',`<p>PalWaypoint is an unofficial fan project. Game names and artwork belong to Pocketpair.</p><h2>Team planning</h2><p>The team builder uses independently read game build 25246127 for Pal stats, friendship growth, passive effects and acquisition flags, condenser costs, souls, EXP and IV fruits. Its calculation order and native default constants follow <a href="https://github.com/arkive-games/arkive/blob/18acc078dbb275c9ceed8a15511d498fe9e544d5/docs/superpowers/specs/2026-07-19-palworld-stat-formula.md">Arkive’s native-inspection stat specification</a>, credited to Yihao Liu (tc-imba), CC BY-NC 4.0. The predictions are baselines; conditional buffs and server rules can change in-game results.</p><h2>Data</h2><p><a href="https://github.com/Awy64/palworld-atlas-data">Palworld Atlas Data</a> provides server-derived Pal and item records under the MIT license. Snapshot: Steam build ${esc(data.metadata.atlasBuild)}, generated ${esc(data.metadata.atlasGenerated)}.</p><p><a href="https://github.com/arkive-games/arkive">Arkive</a> provides independently extracted game tables for skills, recipes, ranch, technology, breeding, fishing, shops and base progression. Its dataset is credited to Yihao Liu (tc-imba), under CC BY-NC 4.0. Item portraits come from its independent game-resource extraction and are served locally; the underlying artwork belongs to Pocketpair. Imported September 30, 2026; its endpoint does not specify a matching game build.</p><p><a href="https://paldb.cc/en/Pals">PalDB</a> supplies the numbered roster reference, game portraits and additional resource, fishing and dungeon locations.</p><p>All map locations, loot tables and artwork use independently extracted game resources. Detailed map sources are in <a href="./MARKER-DATA-LICENSE.txt">map data credits</a>. New wiki data credits are in <a href="./WIKI-DATA-LICENSE.txt">wiki data credits</a>.</p><h2>Coverage</h2><p>The map currently includes 16,401 source-backed location pins across both maps and 1,173 tracked locations. Coverage includes direct extraction of Steam build 25246127, independent game datasets and PalDB's public game-map records. Resource clusters now use game placement groups. Eighteen cave entrance areas have been recovered from game geometry and are marked approximate. One historical camp position and one NPC classification still need verification. Wild habitat and field-spawn data covers 265 Pals. Unverified locations are omitted. Source versions differ, and some item records may be unused or unavailable. Missing data is left unspecified. Effigy upgrades use installed-game tables. Breeding supports both parent-to-offspring and offspring-to-parent searches. Base research and raid planning remain future work.</p>`],privacy:['Privacy','How this release stores progress.',`<p>PalWaypoint stores location completion and Pal capture status in your browser’s local storage. The site code does not upload those records, require an account, or send them to other players.</p><p>The field guide and map load files from our GitHub Pages host. The host can process normal request information. This release does not include site analytics or advertising scripts.</p><p>Clearing this site’s browser data deletes your locally stored progress. Links to independent sources take you to their websites, which have their own privacy practices.</p>`],changelog:['Changelog','Changes to PalWaypoint.',`<h2>October 2, 2026 · Spawn heatmaps &amp; 5/5 captures</h2><p>Capture completion now uses the installed game’s five-capture threshold throughout the map and field guide, preserving saved statuses. Added game-derived habitat heatmaps with All, Day and Night views, and encounter panels showing complete field groups, levels, pack sizes and conditional weighted chances. Overlapping areas and day/night denominators stay separate.</p><h2>October 2, 2026 · Buff previews &amp; inheritance estimates</h2><p>Added party, riding and base-work previews, supported player and element-specific partner bonuses, and a parents-only passive inheritance estimator with average eggs and confidence counts. Unverified final-egg and IV rules remain outside the prediction.</p><h2>October 2, 2026 · Pal team builder</h2><p>Added saved five-Pal teams, current/target stat previews, all 115 visible passives with acquisition routes, natural skill planning, partner-effect summaries and resource requirements. Costs and Pal growth come from installed game build 25246127. Progress backups now include teams.</p><h2>October 2, 2026 · Progress backups, effigies &amp; breeding</h2><p>Added downloadable progress backups with validated merge/replace import previews, all 13 effigy upgrade tracks from installed game files, and reverse breeding search with caught-parent filtering.</p><h2>October 2, 2026 · Marker links & chest grades</h2><p>Added shared location links, Pal and item wiki links, and region-specific chest pool pages with separate grade and slot tables extracted from installed game build 25246127. Centered the compact mobile menu button. Added 18 cave entrance areas with shared exploration tracking.</p><h2>September 30, 2026 · Direct game recovery</h2><p>Read all 9,982 world packages from an installed game archive. Added 2,097 locations, restored awakening tracking and rare-fishing filters, recovered merchant categories and the missing effigy, and linked chests to game loot slots with quantities and weighted chances. Underground locations are labeled. Cave entrances and resource-cluster center reconciliation remain in progress.</p><h2>September 30, 2026 · Independent map sources</h2><p>Rebuilt both location catalogs from independent game extractions. Replaced map artwork dependencies and chest previews, preserved matching progress IDs, and added grade-specific loot tables.</p><h2>September 30, 2026 · Item artwork &amp; unlocks</h2><p>Added game item portraits, schematic requirements, technology links and comma-formatted gold prices to the item catalog and profiles.</p><h2>September 30, 2026 · Field guide</h2><p>Added Pal and item catalogs, Pal profiles, breeding planner, ranch tables, technology, fishing, chest loot, merchant inventories and base progression. Added the map-connected checklist, effigy overview, guide and source notes.</p><h2>September 30, 2026 · Map tracking</h2><p>Added the 288-Pal capture tracker and region hover labels. Improved marker groups during panning and removed the outer circle from individual hexagonal markers.</p>`]};const p=pages[kind];title(p[0],p[1]);content.innerHTML=`<div class="wiki-prose">${p[2]}</div>`;}
function missing(){title('Page not found','Choose a page from the navigation.');content.innerHTML='<a href="#pals">Browse Pals</a>';}
function route(){feedback.textContent='';refresh=()=>{};const [section='pals',rawId]=location.hash.slice(1).split('/');let id;try{id=decodeURIComponent(rawId||'');}catch{id='';}for(const a of document.querySelectorAll('[data-section]'))a.toggleAttribute('aria-current',false);const active=[...document.querySelectorAll('[data-section]')].find(a=>a.dataset.section===(section==='pal'?'pals':section==='item'?'items':section));active?.setAttribute('aria-current','page');document.querySelector('.systems-menu').open=false;const handlers={teams:()=>{title('Pal team builder','Plan five-Pal teams, compare current and target builds, and see the upgrades and traits you need. Teams save automatically in this browser.');const hash=location.hash;renderTeamBuilder(content,data,feedback).then(update=>{if(location.hash===hash&&update)refresh=update;});},pals,items,ranch,breeding,technology:()=>id?technologyProfile(id):technology(),fishing,'chest-loot':()=>chests(id),'base-camp':base,merchants,checklist,effigies,backup,pal:()=>profile(id),item:()=>itemProfile(id),guide:()=>prose('guide'),about:()=>prose('about'),privacy:()=>prose('privacy'),changelog:()=>prose('changelog')};(handlers[section||'pals']||missing)();document.querySelector('#wiki-source').innerHTML=section==='teams'?'Build 25246127 supplies Pal stats, trust growth, passive effects and upgrade costs. The stat model follows independent native inspection by Arkive (CC BY-NC 4.0). Baseline stats and scoped party/riding/base buff previews use explicit conditions. <a href="#about">Sources</a>.':section==='chest-loot'?'Loot weights, chest grades, quantities and slot activation come from installed game build 25246127. Item artwork and names use the independently extracted item catalog. <a href="#about">Sources</a>.':section==='checklist'||section==='effigies'||section==='backup'?'Location counts use the current map catalog. Effigy costs and effects use installed game build 25246127. Progress stays on your browser; backup files are processed locally. <a href="#about">Coverage & sources</a>.':'Game tables: <a href="https://github.com/Awy64/palworld-atlas-data">Palworld Atlas Data</a> (MIT) and <a href="https://github.com/arkive-games/arkive">Arkive</a> (CC BY-NC 4.0). Imported September 30, 2026. <a href="#about">Coverage & sources</a>.';}
content.addEventListener('click',event=>{const button=event.target.closest('[data-capture]');if(!button)return;try{cycleCapture(localStorage,button.dataset.capture);refresh();document.querySelector(`[data-capture="${button.dataset.capture}"]`)?.focus();feedback.textContent='Capture status saved on this browser.';}catch{feedback.textContent='Could not save in this browser. Your previous status has been kept.';}});
content.addEventListener('change',event=>{const checkbox=event.target.closest('[data-location]');if(!checkbox)return;try{toggleCompleted(localStorage,checkbox.dataset.location,checkbox.checked);refresh();feedback.textContent='Saved. Your map uses the same progress.';}catch{checkbox.checked=!checkbox.checked;feedback.textContent='Could not save in this browser. Your previous status has been kept.';}});
window.addEventListener('hashchange',()=>{if(data){route();window.scrollTo(0,0);}});
window.addEventListener('storage',e=>{if([markerStorageKey,captureStorageKey,teamStorageKey].includes(e.key)||e.key===null)refresh();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.systems-menu').open=false;});
try{const response=await fetch('./wiki-data.json?v=recovery-2');if(!response.ok)throw Error('Data unavailable');data=await response.json();palsById=new Map(data.pals.map(p=>[p.id,p]));itemMap=new Map(data.items.map(i=>[i.id,i]));techMap=new Map(data.techs.map(t=>[t.id,t]));route();}catch{title('Field guide unavailable','The data could not load. Check your connection and retry.');content.innerHTML='<button id="retry">Retry</button>';document.querySelector('#retry').onclick=()=>location.reload();}
